mkdir -p demo_proj && cat > demo_proj/processor.py <<'PY'
"""Demo payment processor for CodePrism smoke test."""
import hashlib

def compute_checksum(data: str) -> str:
    return hashlib.sha256(data.encode()).hexdigest()

def process_payment(amount: float, card: str) -> str:
    checksum = compute_checksum(card)
    return charge_card(amount, checksum)

def charge_card(amount: float, token: str) -> str:
    return f"charged {amount} with {token[:8]}"

class PaymentService:
    def refund(self, tx: str) -> str:
        return self._reverse(tx)

    def _reverse(self, tx: str) -> str:
        return f"reversed {tx}"
PY
cat > demo_proj/auth.py <<'PY'
"""Auth module."""
import os

def login(user: str, password: str) -> bool:
    return check_password(user, password)

def check_password(user: str, password: str) -> bool:
    return len(password) > 0
